t=defaultdict(float)
odd=[]
for r in rows:
    if not isinstance(r.get("amount"),(int,float)) or not r.get("region"): odd.append({k:v for k,v in r.items() if k!="detail"})
    t[r.get("region")]+=r.get("amount") or 0
return {"t":{k:round(v,2) for k,v in sorted(t.items(), key=lambda x:str(x[0]))},"odd":odd,"statuses":sorted(set(r.get("status") for r in rows)),"uniq":len(set(r["order_id"] for r in rows))}

